1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"unicode"
9	)
10	
11	// This file holds the shared structural validation for the single-object
12	// JSON registration documents: rule versions (rules.go) and suppression
13	// conditions (alerts.go). Both must contain exactly one JSON object with
14	// nothing but whitespace around it and with no field declared twice in the
15	// same object; the scan runs before the typed decoder reads any business
16	// value, so strings and numbers are never normalized here.
17	//
18	// The two document families keep their own public wording and sentinel
19	// errors, their own idea of which nested objects carry a field table of
20	// their own, and their own way of detecting content after the closing
21	// brace. Those differences are injected through specPolicy; the tokenizing
22	// machinery below exists once.
23	
24	// specPolicy configures scanJSONObject for one registration document
25	// family.
26	type specPolicy struct {
27		// topObject labels the root object in duplicate-field errors.
28		topObject string
29		// known maps the case-folded spelling of every accepted root field to
30		// its canonical name. Folding matches the decoder's field matching, so
31		// spellings like "ſeverity" (U+017F for s) fold onto "severity".
32		known map[string]string
33		// nested names the known fields whose value is itself an object that
34		// must carry its own per-object duplicate table. Any other object or
35		// array value is consumed without looking inside.
36		nested map[string]nestedObjectSpec
37		// rejectExactUnknown makes an exact re-spelling of even an unknown key
38		// (same bytes after JSON unescaping) a duplicate. Case-only variants of
39		// unknown keys stay undetected here and surface as unknown fields in
40		// the typed decode.
41		rejectExactUnknown bool
42	
43		// firstTokenError reports a failure to read any first token (including
44		// empty input, which surfaces as io.EOF).
45		firstTokenError func(err error) error
46		// nonObject reports a first token that is not an opening brace.
47		nonObject func(tok json.Token) error
48		// wrap prefixes syntax errors found while scanning the object.
49		wrap func(err error) error
50		// duplicate reports a repeated field. For known fields field is the
51		// canonical name; for an exact unknown-key repeat it is the key itself.
52		// first is the earlier spelling, spelling the current one.
53		duplicate func(obj, field, first, spelling string) error
54		// trailing reports content after the closing brace, given the raw
55		// document and the byte offset just past it.
56		trailing func(raw []byte, offset int) error
57	}
58	
59	// scanJSONObject proves raw holds exactly one JSON object with no repeated
60	// field in any scanned object and with no content after it beyond what the
61	// policy's trailing check allows. It never interprets values.
62	func scanJSONObject(raw []byte, p specPolicy) error {
63		dec := json.NewDecoder(bytes.NewReader(raw))
64		first, err := dec.Token()
65		if err != nil {
66			return p.firstTokenError(err)
67		}
68		if d, ok := first.(json.Delim); !ok || d != '{' {
69			return p.nonObject(first)
70		}
71		if err := scanObject(dec, p, p.known, p.topObject); err != nil {
72			return err
73		}
74		return p.trailing(raw, int(dec.InputOffset()))
75	}
76	
77	// scanObject consumes one object whose opening brace has already been read
78	// and checks its keys against known. obj names the object for duplicate
79	// errors. Objects named in the policy's nested table are scanned with that
80	// table; every other container is skipped without looking inside.
81	func scanObject(dec *json.Decoder, p specPolicy, known map[string]string, obj string) error {
82		seen := make(map[string]string, len(known))
83		spellings := make(map[string]string)
84		for dec.More() {
85			keyTok, err := dec.Token()
86			if err != nil {
87				return p.wrap(err)
88			}
89			key, ok := keyTok.(string)
90			if !ok {
91				return p.wrap(fmt.Errorf("object key is %s, want string", jsonTokenName(keyTok)))
92			}
93			target, knownKey := known[foldName(key)]
94			if p.rejectExactUnknown {
95				// An exact repeat of a decoded key name (known or unknown) is a
96				// duplicate; escapes are decoded first, so "id" == "id".
97				if first, dup := spellings[key]; dup {
98					return p.duplicate(obj, key, first, key)
99				}
100				spellings[key] = key
101			}
102			if knownKey {
103				// Another spelling of the same known field is the same field:
104				// "Severity", "severity" and "ſeverity" cannot share one object.
105				if first, dup := seen[target]; dup {
106					return p.duplicate(obj, target, first, key)
107				}
108				seen[target] = key
109			}
110			start, err := dec.Token()
111			if err != nil {
112				return p.wrap(err)
113			}
114			if d, isDelim := start.(json.Delim); isDelim {
115				switch d {
116				case '{':
117					nested, hasShape := p.nested[target]
118					if !knownKey || !hasShape {
119						if err := skipContainer(dec, p); err != nil {
120							return err
121						}
122						continue
123					}
124					if err := scanObject(dec, p, nested.fields, nested.label); err != nil {
125						return err
126					}
127				case '[':
128					if err := skipContainer(dec, p); err != nil {
129						return err
130					}
131				}
132				continue
133			}
134		}
135		closeTok, err := dec.Token()
136		if err != nil {
137			return p.wrap(err)
138		}
139		if closeTok != json.Delim('}') {
140			return p.wrap(fmt.Errorf("expected closing brace, got %s", jsonTokenName(closeTok)))
141		}
142		return nil
143	}
144	
145	// skipContainer consumes the remainder of one object or array whose
146	// opening delimiter has already been read, balancing nested brackets. The
147	// scanner itself rejects mismatched brackets, so only depth bookkeeping is
148	// needed here.
149	func skipContainer(dec *json.Decoder, p specPolicy) error {
150		depth := 1
151		for depth > 0 {
152			tok, err := dec.Token()
153			if err != nil {
154				return p.wrap(err)
155			}
156			if d, ok := tok.(json.Delim); ok {
157				switch d {
158				case '{', '[':
159					depth++
160				case '}', ']':
161					depth--
162				}
163			}
164		}
165		return nil
166	}
167	
168	// jsonTokenName describes a token the way the structural error messages do.
169	func jsonTokenName(tok json.Token) string {
170		switch t := tok.(type) {
171		case json.Delim:
172			switch t {
173			case '[':
174				return "array"
175			case '{':
176				return "object"
177			case ']':
178				return "extra closing bracket ']'"
179			case '}':
180				return "extra closing brace '}'"
181			}
182		case nil:
183			return "null"
184		case bool:
185			return "boolean"
186		case string:
187			return "string"
188		case json.Number:
189			return "number"
190		case float64:
191			return "number"
192		case int64:
193			return "number"
194		}
195		return "value"
196	}
197	
198	// trailingTokenName identifies the kind of JSON token started by the first
199	// non-whitespace byte after a closed object.
200	func trailingTokenName(b byte) string {
201		switch b {
202		case '{':
203			return "object"
204		case '[':
205			return "array"
206		case '}':
207			return "extra closing brace '}'"
208		case ']':
209			return "extra closing bracket ']'"
210		case '"':
211			return "string"
212		case 't', 'f':
213			return "boolean"
214		case 'n':
215			return "null"
216		default:
217			if (b >= '0' && b <= '9') || b == '-' {
218				return "number"
219			}
220			return fmt.Sprintf("unexpected character %q", rune(b))
221		}
222	}
223	
224	// fieldTable maps the case-folded spellings of a struct object's JSON
225	// fields to their canonical names. Folding follows the decoder's field
226	// matching (see foldName), not plain lowercasing.
227	func fieldTable(fields ...string) map[string]string {
228		table := make(map[string]string, len(fields))
229		for _, f := range fields {
230			table[foldName(f)] = f
231		}
232		return table
233	}
234	
235	// foldName normalizes a JSON object key the way encoding/json matches
236	// struct field names: every rune is replaced by the smallest rune of its
237	// Unicode simple case-folding orbit. Besides ASCII case this also folds
238	// compatibility spellings the decoder accepts, such as "ſ" (U+017F, Latin
239	// small long s) onto "s" and "K" (U+212A, Kelvin sign) onto "k", so a key
240	// like "ſeverity" names the same field as "severity" here too.
241	func foldName(s string) string {
242		var b strings.Builder
243		b.Grow(len(s))
244		for _, r := range s {
245			b.WriteRune(foldRune(r))
246		}
247		return b.String()
248	}
249	
250	// foldRune returns the smallest rune in r's simple case-folding orbit,
251	// mirroring the fold encoding/json applies to field names.
252	func foldRune(r rune) rune {
253		for {
254			r2 := unicode.SimpleFold(r)
255			if r2 <= r {
256				return r2
257			}
258			r = r2
259		}
260	}
261	
262	// nestedObjectSpec pairs a nested object's field table with the label used
263	// in its duplicate-field errors.
264	type nestedObjectSpec struct {
265		fields map[string]string
266		label  string
267	}
268

