48			if s.TxHash == victim {
49				pos = i
50				break
51			}
52		}
53		var front, back *Swap
54		if pos > 0 {
55			front = &pool[pos-1]
56		}
57		if pos >= 0 && pos+1 < len(pool) {
58			back = &pool[pos+1]
59		}
60		j, hit := judgeVictim(front, target, back, rules)
61		if !hit {
62			return nil
63		}
64		if j.kind == "sandwich" {
65			return []Finding{{
66				TxHash: victim, Kind: j.kind, Severity: j.severity,
67				Evidence: []string{
68					"front-run by " + front.Trader + " at gas " + strconv.FormatInt(front.GasPrice, 10),
69					"back-run by " + back.Trader + " at gas " + strconv.FormatInt(back.GasPrice, 10),
70					"victim gas " + strconv.FormatInt(target.GasPrice, 10),
71				},
72			}}
73		}
74		return []Finding{{TxHash: victim, Kind: j.kind, Severity: j.severity,
75			Evidence: []string{"front gas dominates victim by more than 2x"}}}
76	}
77	
78	// findSwap returns the record whose TxHash equals hash. TxHash is unique
79	// among the valid records replay accepts.
80	func findSwap(swaps []Swap, hash string) (Swap, bool) {
81		for _, s := range swaps {
82			if s.TxHash == hash {
83				return s, true
84			}
85		}
86		return Swap{}, false
87	}
88	
89	// Rank orders findings by severity then hash.
90	func Rank(findings []Finding) []Finding {
91		sorted := append([]Finding(nil), findings...)
92		sort.Slice(sorted, func(i, j int) bool {
93			if sorted[i].Severity == sorted[j].Severity {
94				return sorted[i].TxHash < sorted[j].TxHash
95			}
96			return sorted[i].Severity > sorted[j].Severity
97		})
98		return sorted
99	}
